from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='La genética mendeliana explica cómo se transmiten los caracteres de padres a hijos, y la genética de poblaciones estudia cómo se reparten los alelos en un grupo de individuos. Este capítulo presenta los experimentos de Mendel, los conceptos de alelo, dominante y recesivo, y el principio de Hardy-Weinberg, y lo aplica a un cálculo de portadores de una enfermedad recesiva.',
        quotes=[Q('es_mendel','Las leyes de Mendel (en conjunto conocidas como genética mendeliana) son el conjunto de reglas básicas sobre la transmisión por herencia genética de las características de los organismos progenitores a su descendencia.'), Q('en_hw','states that allele and genotype frequencies in a population will remain constant from generation to generation in the absence of other evolutionary influences')]))
    P.append(dict(text='Gregor Mendel fue un monje agustino que cultivó y estudió unos 28 000 guisantes entre 1856 y 1863. Presentó sus experimentos en la Sociedad de Historia Natural de Brno los días 8 de febrero y 8 de marzo de 1865, y se publicaron en 1866. Sus resultados fueron en gran parte ignorados y se redescubrieron en 1900. Una de las fuentes lo valora como un hito comparable, en biología, a las leyes de Newton en física, y destaca que expresó los resultados de forma cuantitativa mediante la estadística.',
        quotes=[Q('en_mendel','Between 1856 and 1863, Mendel cultivated and tested some 28,000 pea plants.'), Q('es_mendel','publicado en 1865 y en 1866, aunque fue ignorado durante mucho tiempo hasta su redescubrimiento en 1900'), Q('es_mendel','la expresión de los resultados observacionales en forma cuantitativa mediante el recurso de la estadística')]))
    P.append(dict(text='La teoría de la herencia por mezcla suponía que los caracteres se transmiten por fluidos que, una vez mezclados, no se pueden separar. Frente a ella, Mendel formuló una teoría con unidades discretas. Una fuente señala que un obstáculo para entender su importancia fue que los biólogos del siglo XIX daban mucho peso a la aparente mezcla de muchos rasgos heredados, que hoy se sabe debida a interacciones entre varios genes, a diferencia de los caracteres binarios que estudió Mendel.',
        quotes=[Q('es_mendel','La teoría de la herencia por mezcla suponía que los caracteres se transmiten de padres a hijos mediante fluidos corporales que, una vez mezclados, no se pueden separar'), Q('en_mendel','now known to be due to multi-gene interactions, in contrast to the organ-specific binary characters studied by Mendel')]))
    P.append(dict(text='Un alelo es una de las versiones de una secuencia de ADN en una posición concreta del genoma. Cada individuo hereda dos alelos, uno de cada progenitor. Si los dos son iguales es homocigoto para ese alelo, y si son distintos, heterocigoto. Si los alelos de un gen son diferentes, uno se expresa, que es el dominante, y el efecto del otro, llamado recesivo, queda enmascarado. Un rasgo recesivo solo se expresa cuando están presentes las dos copias del alelo.',
        quotes=[Q('nhgri_allele','An individual inherits two alleles, one from each parent, for any given genomic location where such variation exists.'), Q('nhgri_dominant','If the alleles of a gene are different, one allele will be expressed; it is the dominant gene.'), Q('nhgri_recessive','both (recessive) alleles must be present to express the trait')]))
    P.append(dict(text='En un cruce monohíbrido entre dos heterocigotos, Aa por Aa, los descendientes son AA, Aa, Aa y aa, de modo que una cuarta parte es homocigota dominante, la mitad es heterocigota y una cuarta parte es homocigota recesiva. La razón genotípica es 1:2:1 y la fenotípica, 3:1, es decir, tres cuartos con el carácter dominante y un cuarto con el recesivo. En los cruces dihíbridos Mendel encontró proporciones 9:3:3:1, lo que muestra que cada par de alelos se hereda de forma independiente, con una razón fenotípica de 3:1 para cada uno.',
        quotes=[Q('en_mendel','In his monohybrid crosses, an idealized 3:1 ratio between dominant and recessive phenotypes resulted.'), Q('es_mendel','comprobó que la proporción era de 3/4 de color amarillo y 1/4 de color verde (3:1)'), Q('en_mendel','The genotypic ratio is 1: 2 : 1, and the phenotypic ratio is 3: 1.'), Q('en_mendel','In dihybrid crosses, however, he found a 9:3:3:1 ratios.')]))
    P.append(dict(text='Las proporciones de Mendel son esperanzas, no resultados exactos en cada familia. Una fuente indica que, según las leyes de Mendel, existe un 25 % de probabilidad en cada embarazo de que ambos padres portadores transmitan el alelo mutado de una enfermedad recesiva, con independencia del sexo del hijo. Esa probabilidad se aplica por separado a cada embarazo y no se acumula: haber tenido un hijo afectado no cambia el 25 % del siguiente.',
        quotes=[Q('es_mendel','existe un 25 % en cada embarazo, de que ambos padres trasmitan el alelo mutado, independientemente del sexo del nuevo individuo'), Q('en_mendel','an average of 25% are homozygous with the dominant trait, 50% are heterozygous showing the dominant trait in the phenotype (genetic carriers), 25% are homozygous with the recessive trait')]))
    P.append(dict(text='El principio de Hardy-Weinberg establece que las frecuencias de alelos y de genotipos de una población se mantienen constantes de una generación a otra mientras no actúen otras influencias evolutivas, como la selección natural, la mutación, la deriva genética o el flujo génico. Lo establecieron de forma independiente en 1908 el matemático G. H. Hardy y el médico Wilhelm Weinberg. En su forma más simple, con un locus de dos alelos A y a de frecuencias p y q, predice las frecuencias p² para AA, 2pq para Aa y q² para aa.',
        quotes=[Q('en_hw','allele and genotype frequencies in a population will remain constant from generation to generation in the absence of other evolutionary influences'), Q('es_hw','que establecieron el teorema independientemente en 1908'), Q('es_hw','el PHW predice que la frecuencia genotípica para el homocigoto dominante AA es p2, la del heterocigoto Aa es 2pq y la del homocigoto recesivo aa es q2')]))
    P.append(dict(text='El principio permite estimar la frecuencia de portadores de una enfermedad recesiva a partir de la frecuencia de enfermos. Una fuente en español lo ilustra con la fenilcetonuria: su incidencia es de 0,0001, que corresponde a q², de modo que q es la raíz cuadrada, 0,01; la enfermedad afecta a 1 de cada 10 000 individuos pero la frecuencia del gen es 100 veces mayor, 1 de cada 100. La fuente en inglés usa la fibrosis quística, con 1 de cada 2500 recién nacidos homocigotos en poblaciones del norte de Europa, de donde q es 1/50 y los portadores, 2pq, son aproximadamente 1/25.',
        quotes=[Q('es_hw','La frecuencia q del gen a será la raíz cuadrada de 0,0001, es decir, 0,01.'), Q('es_hw','La enfermedad tiene una incidencia de 1 cada 10 000 individuos, pero la frecuencia del gen es 100 veces mayor, 1 cada 100.'), Q('en_hw','babies are born with cystic fibrosis, this is about the frequency of homozygous individuals observed in Northern European populations')]))
    P.append(dict(text='La suma de las tres frecuencias genotípicas es la unidad: p² + 2pq + q² = (p + q)² = 1. Por eso, conocido q, el resto sale por cálculo: p es el complemento de q. La fuente en inglés toma p como 1 cuando q es pequeño, lo que da unos 2/50, es decir, 1/25; el cálculo exacto con p igual a 0,98 y q igual a 0,02 da 2 × 0,98 × 0,02, es decir, 0,0392 o un 3,92 %. La diferencia entre el 4 % y el 3,92 % es el error de esa aproximación de p.',
        quotes=[Q('es_hw','p² + 2pq + q² = (p + q)² = 1'), Q('en_hw','We can use the Hardy–Weinberg equations to estimate the carrier frequency, the frequency of heterozygous individuals,')]))
    P.append(dict(role='definition', text='Equilibrio de Hardy-Weinberg: situación en la que, para un locus con dos alelos de frecuencias p y q, las frecuencias genotípicas son p², 2pq y q² y se mantienen constantes de una generación a otra mientras no actúen la selección, la mutación, la deriva ni otras fuerzas evolutivas.',
        quotes=[Q('en_hw','In the absence of selection, mutation, genetic drift, or other forces, allele frequencies p and q are constant between generations, so equilibrium is reached.'), Q('es_hw','Es decir, la herencia mendeliana, por sí misma, no engendra cambio evolutivo.')]))
    P.append(dict(role='consejo', text='Al aplicar Hardy-Weinberg, anote qué condición supone: apareamiento al azar y ausencia de selección, mutación y deriva. Si la población no cumple esas condiciones, el resultado es una estimación y no un valor medido; por eso se usa para contrastar si hay estratificación u otras formas de apareamiento no aleatorio.',
        quotes=[Q('en_hw','tests for Hardy–Weinberg genotype frequencies are used primarily to test for population stratification and other forms of non-random mating'), Q('es_hw','mientras no actúe la selección natural ni ningún otro factor y no se produzca ninguna mutación')]))
    P.append(dict(role='self_check', text='¿Qué proporciones fenotípicas da un cruce monohíbrido entre heterocigotos? ¿Qué predice Hardy-Weinberg para las frecuencias genotípicas? Si 1 de cada 10 000 individuos padece una enfermedad recesiva, ¿qué fracción lleva el alelo en estado heterocigoto, aproximadamente?',
        quotes=[Q('en_mendel','In a dominant-recessive inheritance, an average of 25% are homozygous with the dominant trait'), Q('es_hw','Los tres genotipos AA : Aa : aa aparecen en una relación p² : 2pq : q²')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='En poblaciones del norte de Europa nace con fibrosis quística 1 de cada 2500 bebés, la frecuencia de homocigotos recesivos. Suponiendo equilibrio de Hardy-Weinberg, calcule la frecuencia q del alelo y el porcentaje exacto de portadores heterocigotos, 2pq.',
        expected='3.92', quotes=[Q('en_hw','babies are born with cystic fibrosis, this is about the frequency of homozygous individuals observed in Northern European populations'), Q('es_hw','Los tres genotipos AA : Aa : aa aparecen en una relación p² : 2pq : q²')],
        method='Principio de Hardy-Weinberg para un alelo recesivo',
        solution=dict(given=[dict(symbol='q2',value=0.0004,unit='dimensionless',meaning='frecuencia de homocigotos recesivos, 1/2500')],
          unknown='La frecuencia del alelo recesivo y la de portadores.',
          model=[dict(name='Alelo recesivo',latex='q = \\sqrt{q^{2}}',symbolic='sqrt(q2)'),dict(name='Portadores',latex='2pq = 2(1-q)\\,q',symbolic='2*(1-sqrt(q2))*sqrt(q2)')],
          assumptions=['La población está en equilibrio de Hardy-Weinberg: apareamiento al azar, sin selección, mutación ni deriva apreciables.','La enfermedad es autosómica recesiva con un solo locus de dos alelos.'],
          development=['La frecuencia de enfermos es q², porque solo los homocigotos recesivos están afectados; los portadores son los heterocigotos.'],
          steps=[dict(text='Frecuencia del alelo',equation='q = \\sqrt{1/2500}',expression='sqrt(1/2500)',expected=0.02,unit='dimensionless'),
                 dict(text='Frecuencia de portadores',equation='2pq = 2(0{,}98)(0{,}02)',expression='2*0.98*0.02',expected=0.0392,unit='dimensionless')],
          result='La frecuencia del alelo es q = 0,02 (1 de cada 50) y los portadores son el 3,92 % de la población, aproximadamente 1 de cada 25.',
          interpretation='Aunque solo 1 de cada 2500 bebés padece la enfermedad, unas 1 de cada 25 personas porta el alelo, lo que explica que la enfermedad aparezca en familias sin antecedentes.',
          limitations=['El resultado depende del supuesto de equilibrio y de que la incidencia de 1/2500 sea correcta; la fuente la da como aproximada.'],
          mistakes=['Tomar q² como la frecuencia del alelo en lugar de su raíz cuadrada.']))]


